-- Bug-hunt 2026-07-30 (P3): mon_mv_refresh_log had NEVER been populated, so mon_detect_stale_refresh
-- ran forever on its self-described interim proxy (pg_stat_user_tables.last_analyze). Append a log
-- insert to both refresh crons so the detector's primary path finally has data; the ANALYZE fallback
-- stays as a safety net.
select cron.alter_job(17, command := $cmd$set statement_timeout to '900s'; refresh materialized view concurrently public.active_listing_ids_v2; refresh materialized view concurrently public.listing_native_location_v1; analyze public.active_listing_ids_v2; analyze public.listing_native_location_v1; insert into public.mon_mv_refresh_log(object_name, refreshed_at, rows_after, note) select 'active_listing_ids_v2', now(), count(*), 'jobid17' from public.active_listing_ids_v2; insert into public.mon_mv_refresh_log(object_name, refreshed_at, rows_after, note) select 'listing_native_location_v1', now(), count(*), 'jobid17' from public.listing_native_location_v1;$cmd$);
select cron.alter_job(16, command := $cmd$set statement_timeout to '1200s'; refresh materialized view concurrently public.listing_location_index; refresh materialized view concurrently public.listing_location_canonical_mv; analyze public.listing_location_index; analyze public.listing_location_canonical_mv; insert into public.mon_mv_refresh_log(object_name, refreshed_at, rows_after, note) select 'listing_location_index', now(), count(*), 'jobid16' from public.listing_location_index; insert into public.mon_mv_refresh_log(object_name, refreshed_at, rows_after, note) select 'listing_location_canonical_mv', now(), count(*), 'jobid16' from public.listing_location_canonical_mv;$cmd$);